    reject!(Internal("dart2wasm/lib/functions.dart:646 _FunctionTypeGenerator._getConstructorBodyType: a constructor body's type; Julia's constructor is an ordinary method, typed as any member (visitProcedure), its allocation the %new statement, with no allocator, initializer list or separate body (the Kernel table's Constructor row)"), "_FunctionTypeGenerator._getConstructorBodyType")

# a Julia constructor's inputs are any method's (_getInputTypes)
@parity "dart2wasm/lib/functions.dart:697 _getConstructorInputTypes" _get_constructor_input_types(translator::Translator, member::Core.MethodInstance, type_parameters::Vector{TypeVar}, parameters::Vector{NirArgument}, translate_type::Function; is_body_parameter::Bool = false)::Union{} =
    reject!(Internal("dart2wasm/lib/functions.dart:697 _getConstructorInputTypes: a constructor's input types; Julia's constructor is an ordinary method, typed as any member (visitProcedure), its allocation the %new statement, with no allocator, initializer list or separate body (the Kernel table's Constructor row)"), "_getConstructorInputTypes")

# a Julia member has no type parameters (its MethodInstance binds them) and no named parameters; its
# parameters are the arguments after the callee, each of the type it is specialized on
@parity "dart2wasm/lib/functions.dart:731 _getInputTypes" function _get_input_types(translator::Translator, target::Core.MethodInstance, receiver_type::Union{Nothing,WasmBuilder.IR.ValueType},
        is_import_or_export::Bool, translate_type::Function)::Vector{WasmBuilder.IR.ValueType}
    local params = (Base.unwrap_unionall(target.specTypes)::DataType).parameters
    local inputs = WasmBuilder.IR.ValueType[]
    if receiver_type !== nothing
        is_import_or_export && reject!(Internal("dart2wasm/lib/functions.dart:731 _getInputTypes: an import or export with a receiver"), "_getInputTypes")
        push!(inputs, receiver_type)
    end
    for p in params[2:end]
        push!(inputs, translate_type(p)::WasmBuilder.IR.ValueType)
    end
    return inputs
end

"""
The signature of the body a member's checked and unchecked entries share: its receiver (the callee,
a closure's context, dart's this), each parameter's checked type (typeOfCheckedParameterVariable),
then its return. A Julia method has no type parameters (its MethodInstance binds them) and no named
ones.
"""
@parity "dart2wasm/lib/functions.dart:787 makeFunctionTypeForBody" function make_function_type_for_body(translator::Translator, member::Core.MethodInstance, synthesize_null_return_value::Bool, synthesize_no_return::Bool)::WasmBuilder.IR.FunctionType
    local params = (Base.unwrap_unionall(member.specTypes)::DataType).parameters
    # dart asserts an instance member: a Julia member whose callee is a value, no singleton function
    Base.issingletontype(params[1]) && reject!(Internal("dart2wasm/lib/functions.dart:793 makeFunctionTypeForBody: $(member) has no receiver"), "make_function_type_for_body")
    local inputs = WasmBuilder.IR.ValueType[translate_type(translator, params[1])]
    for i in 2:length(params)
        push!(inputs, translate_type(translator, type_of_checked_parameter_variable(translator, member, i)))
    end
    local has_no_return_value = synthesize_null_return_value || synthesize_no_return
    local outputs = has_no_return_value ? WasmBuilder.IR.ValueType[] : WasmBuilder.IR.ValueType[translate_return_type(translator, type_of_return_value(translator, member))]
    return WasmBuilder.define_function(types_builder(translator), inputs, outputs)
end

@parity "dart2wasm/lib/functions.dart:821 makeDynamicDispatcherSignature" make_dynamic_dispatcher_signature(translator::Translator, shape::CallShape)::WasmBuilder.IR.FunctionType = _make_dynamic_signature(translator, shape, true)

@parity "dart2wasm/lib/functions.dart:826 makeDynamicForwarderSignature" make_dynamic_forwarder_signature(translator::Translator, shape::CallShape)::WasmBuilder.IR.FunctionType = _make_dynamic_signature(translator, shape, false)

"""
A dynamic call's signature by its shape: the receiver (the top type, nullable for a dispatcher), a
type argument for each the shape passes (Julia's Type, dart's typeType), and the top type for each
other argument and for the result, none for a setter or an index set.
"""
@parity "dart2wasm/lib/functions.dart:831 _makeDynamicSignature" function _make_dynamic_signature(translator::Translator, shape::CallShape, nullable_receiver::Bool)::WasmBuilder.IR.FunctionType
    local top = translator.top_type[]
    local receiver = nullable_receiver ? top : translator.top_type_non_nullable[]
    return @exhaustive shape::CallShape begin
        GetterCallShape => WasmBuilder.define_function(types_builder(translator), WasmBuilder.IR.ValueType[receiver], WasmBuilder.IR.ValueType[top])
        SetterCallShape => WasmBuilder.define_function(types_builder(translator), WasmBuilder.IR.ValueType[receiver, top], WasmBuilder.IR.ValueType[])
        (m::MethodCallShape) => WasmBuilder.define_function(types_builder(translator),
            WasmBuilder.IR.ValueType[receiver;
                                     WasmBuilder.IR.ValueType[translate_type(translator, type_type(translator.types[])) for _ in 1:m.type_count];   # dart's loop: none translated for none
                                     fill(top, m.positional_count);
                                     fill(top, length(m.named))],
            is_index_set(m) ? WasmBuilder.IR.ValueType[] : WasmBuilder.IR.ValueType[top])
    end
end

# a tear-off returns the function as a value: dart's computeFunctionType; a Julia method's value is its
# callee, of the type its specialization's first parameter is
@parity "dart2wasm/lib/functions.dart:860 makeTearOffFunctionType" function make_tear_off_function_type(translator::Translator, function_::NirBody, receiver_type::Union{Nothing,WasmBuilder.IR.ValueType})::WasmBuilder.IR.FunctionType
    local callee = (Base.unwrap_unionall(function_.ci.def.specTypes)::DataType).parameters[1]
    return WasmBuilder.define_function(types_builder(translator), receiver_type === nothing ? WasmBuilder.IR.ValueType[] : WasmBuilder.IR.ValueType[receiver_type],
                                       WasmBuilder.IR.ValueType[translate_type(translator, callee)])
end

# dart's signature returns an Invocation, noSuchMethod's argument record (translator.dart:309's
# invocationType). A Julia program has no noSuchMethod: a call with no method is a MethodError,
# which Julia's trim verifier refuses, so no program WasmTarget compiles reaches this; it rejects,
# naming what Julia lacks, as wt3-translator ruled
@parity "dart2wasm/lib/functions.dart:875 makeInvocationCreatorSignature" function make_invocation_creator_signature(translator::Translator, shape::MethodCallShape)::Union{}
    reject!(Internal("dart2wasm/lib/functions.dart:875 makeInvocationCreatorSignature: an Invocation for $(sprint(show, shape)); Julia has no noSuchMethod, a call with no method being a MethodError the trim verifier refuses (the Kernel table's DynamicInvocation row)"), "make_invocation_creator_signature")
end

# an import's or export's types are the external ones (translateExternalType); a member returning
# only `nothing` returns nothing in an export, dart's void
@parity "dart2wasm/lib/functions.dart:890 _makeFunctionType" function _make_function_type(translator::Translator, target::Core.MethodInstance, receiver_type::Union{Nothing,WasmBuilder.IR.ValueType};
        synthesize_null_return_value::Bool, synthesize_no_return::Bool, is_import_or_export::Bool = false)::WasmBuilder.IR.FunctionType
    # Translate types differently for imports and exports.
    local tt(t::Type) = is_import_or_export ? translate_external_type(translator, t) : translate_type(translator, t)
    local trt(t::Type) = is_import_or_export ? translate_external_type(translator, t) : translate_return_type(translator, t)
    local inputs = _get_input_types(translator, target, receiver_type, is_import_or_export, tt)
    local is_void_type(t::Type) = is_import_or_export && t === Nothing
    local has_no_return_value = synthesize_null_return_value || synthesize_no_return
    local outputs = WasmBuilder.IR.ValueType[]
    if !has_no_return_value
        local return_type = type_of_return_value(translator, target)
        is_void_type(return_type) || push!(outputs, trt(return_type))
    end
    return WasmBuilder.define_function(types_builder(translator), inputs, outputs)
end

# dart's sealed class is abstract: its constructor runs only as a kind's super constructor, whose
# struct holds its field; called on its own it is dart's compile error
@parity "dart2wasm/lib/functions.dart:951 CallShape" function CallShape(name::Symbol)::Union{}
    reject!(Internal("dart2wasm/lib/functions.dart:951 CallShape: the sealed class is constructed only through a kind"), "CallShape")
end

